fun describe(n: Int): String = when (n) {
    0 -> "zero"
    in 1..9 -> "small"
    in 13..19 -> "teen"
    else -> "big"
}

fun main() {
    listOf(0, 7, 15, 42).forEach { println(describe(it)) }
}

