sealed interface Result
data object Loading : Result
data class Success(val items: List<String>) : Result
data class Failure(val reason: String) : Result

fun render(r: Result): String = when (r) {
    Loading -> "loading..."
    is Success -> "${r.items.size} items"
    is Failure -> "failed: ${r.reason}"
}

fun main() {
    listOf(Loading, Success(listOf("a", "b", "c")), Failure("timeout"))
        .forEach { println(render(it)) }
}

